import{c as a,S as r,j as l,m as n}from"./chunks/framework.8aa1YH_s.js";const y=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 5: Türkçede Ünlü (Vokal) Uyumları ve Kuralları","description":"","frontmatter":{},"headers":[],"relativePath":"5 Türkçede Ünlü (Vokal) Uyumları ve Kuralları.md","filePath":"5 Türkçede Ünlü (Vokal) Uyumları ve Kuralları.md"}'),i={name:"5 Türkçede Ünlü (Vokal) Uyumları ve Kuralları.md"};function u(k,e,o,m,d,s){return r(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="turk-dil-bilgisi-serisi-5-turkcede-unlu-vokal-uyumları-ve-kuralları" tabindex="-1">Türk Dil Bilgisi Serisi - 5: Türkçede Ünlü (Vokal) Uyumları ve Kuralları <a class="header-anchor" href="#turk-dil-bilgisi-serisi-5-turkcede-unlu-vokal-uyumları-ve-kuralları" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 5: Türkçede Ünlü (Vokal) Uyumları ve Kuralları”">​</a></h1><p>Önceki bölümlerimizde Türkçedeki 8 asli ünlüyü (vokali) ve onların özelliklerini incelemiştik. Bu yazımızda, o öğrendiğimiz vokal tablosunun üzerine inşa edilen, Türkçeyi dünya dilleri arasında en düzenli ve ahenkli dillerden biri yapan <strong>Ünlü Uyumları</strong> konusunu ele alıyoruz.</p><p>Prof. Dr. Muharrem Ergin&#39;e göre ünlü uyumları, Türkçenin asli ses kanunudur. Dilimize giren yabancı kelimeler bile zamanla bu kanuna uydurulmuştur.</p><hr><h2 id="_1-buyuk-unlu-uyumu-kalınlık-inceleme-uyumu-palatal-harmoni" tabindex="-1">1. Büyük Ünlü Uyumu (Kalınlık-İnceleme Uyumu / Palatal Harmoni) <a class="header-anchor" href="#_1-buyuk-unlu-uyumu-kalınlık-inceleme-uyumu-palatal-harmoni" aria-label="Permalink to “1. Büyük Ünlü Uyumu (Kalınlık-İnceleme Uyumu / Palatal Harmoni)”">​</a></h2><p>Büyük ünlü uyumu, bir kelimenin içindeki ünlülerin ton (çıkış yeri) bakımından gösterdiği uyumdur. Kural son derece basittir:</p><ul><li>Bir kelimenin <strong>ilk hecesinde kalın bir ünlü (a, ı, o, u)</strong> varsa, sonraki hecelerdeki ünlüler de <strong>kalın</strong> olmak zorundadır.</li><li>Bir kelimenin <strong>ilk hecesinde ince bir ünlü (e, i, ö, ü)</strong> varsa, sonraki hecelerdeki ünlüler de <strong>ince</strong> olmak zorundadır.</li></ul><h3 id="ornekler" tabindex="-1">Örnekler: <a class="header-anchor" href="#ornekler" aria-label="Permalink to “Örnekler:”">​</a></h3><ul><li><strong>Uyanlar:</strong> <em>Adım-lar-ımız-dan</em> (Hepsi kalın), <em>Göz-lem-ci-ler-i-miz</em> (Hepsi ince).</li><li><strong>Uymayanlar:</strong> <em>Kitap</em> (i ince, a kalın), <em>Kalem</em> (a kalın, e ince).</li></ul><blockquote><p><strong>Not:</strong> Türkçe kökenli olduğu halde zamanla ses değişimine uğrayarak bu uyumu kaybeden istisnai kelimeler vardır: <em>Hangi</em> (Aslı: Kañı), <em>Kardeş</em> (Aslı: Karındaş), <em>Elma</em> (Aslı: Alma), <em>Şişman</em> (Aslı: Sışman).</p></blockquote><hr><h2 id="_2-kucuk-unlu-uyumu-duzluk-yuvarlaklık-uyumu-labial-harmoni" tabindex="-1">2. Küçük Ünlü Uyumu (Düzlük-Yuvarlaklık Uyumu / Labial Harmoni) <a class="header-anchor" href="#_2-kucuk-unlu-uyumu-duzluk-yuvarlaklık-uyumu-labial-harmoni" aria-label="Permalink to “2. Küçük Ünlü Uyumu (Düzlük-Yuvarlaklık Uyumu / Labial Harmoni)”">​</a></h2><p>Küçük ünlü uyumu, Türkçenin en çok dikkat ve hassasiyet gerektiren ses kanunudur. Bu uyum, ünlülerin <strong>dudak şekline (düz-yuvarlak)</strong> ve <strong>ağız açıklığına (geniş-dar)</strong> göre şekillenir. Kelimenin heceleri arasında <em>adım adım</em> (bir önceki hece bir sonrakini bağlar) kontrol edilir.</p><p>Küçük ünlü uyumunun iki temel kuralı vardır:</p><h3 id="kural-a-duzden-sonra-duz" tabindex="-1">Kural A: Düzden Sonra Düz <a class="header-anchor" href="#kural-a-duzden-sonra-duz" aria-label="Permalink to “Kural A: Düzden Sonra Düz”">​</a></h3><p>Bir hecede <strong>düz bir ünlü (a, e, ı, i)</strong> varsa, ondan hemen sonra gelen hecede de ancak <strong>düz bir ünlü (a, e, ı, i)</strong> bulunabilir.</p><ul><li><em>Formül:</em> <code>a, e, ı, i</code> $$\\rightarrow$$ <code>a, e, ı, i</code></li><li><em>Örnek:</em> <em>Yazıcılar</em> (y-a-z-ı-c-ı-l-a-r) $$\\rightarrow$$ a&#39;dan sonra ı, ı&#39;dan sonra ı, ı&#39;dan sonra a gelmiştir. Kurala tam uyar.</li></ul><h3 id="kural-b-yuvarlaktan-sonra-duz-genis-veya-yuvarlak-dar" tabindex="-1">Kural B: Yuvarlaktan Sonra &quot;Düz-Geniş&quot; veya &quot;Yuvarlak-Dar&quot; <a class="header-anchor" href="#kural-b-yuvarlaktan-sonra-duz-genis-veya-yuvarlak-dar" aria-label="Permalink to “Kural B: Yuvarlaktan Sonra &quot;Düz-Geniş&quot; veya &quot;Yuvarlak-Dar&quot;”">​</a></h3><p>Bir hecede <strong>yuvarlak bir ünlü (o, ö, u, ü)</strong> varsa, ondan hemen sonra gelen hecede ya <strong>düz-geniş (a, e)</strong> ya da <strong>yuvarlak-dar (u, ü)</strong> bir ünlü bulunabilir.</p><ul><li><em>Formül:</em> <code>o, ö, u, ü</code> $$\\rightarrow$$ <code>a, e</code> VEYA <code>u, ü</code></li><li><em>Örnek 1:</em> <em>Koyun</em> (o&#39;dan sonra u gelmiştir; yuvarlaktan sonra yuvarlak-dar kuralına uyar).</li><li><em>Örnek 2:</em> <em>Gözlükçü</em> (ö&#39;den sonra ü, ü&#39;den sonra ü gelmiştir; yuvarlaktan sonra yuvarlak-dar kuralına uyar).</li><li><em>Örnek 3:</em> <em>Odalar</em> (o&#39;dan sonra a gelmiştir; yuvarlaktan sonra düz-geniş kuralına uyar).</li></ul><h3 id="⚠️-altın-degerinde-iki-onemli-uyarı" tabindex="-1">⚠️ Altın Değerinde İki Önemli Uyarı: <a class="header-anchor" href="#⚠️-altın-degerinde-iki-onemli-uyarı" aria-label="Permalink to “⚠️ Altın Değerinde İki Önemli Uyarı:”">​</a></h3><ol><li><strong>Türkçede &quot;o&quot; ve &quot;ö&quot; sesleri sadece İLK HECEDE bulunabilir.</strong> Sonraki hecelerde o/ö sesi olan hiçbir kelime asli Türkçe değildir (Örn: <em>Doktor, Horoz, Balon</em> - hepsi yabancıdır).</li><li>Küçük ünlü uyumu aranırken kelimenin bütününe birden bakılmaz; heceler zincirleme olarak birbirini takip eder. (1 $$\\rightarrow$$2, 2$$\\rightarrow$$3, 3$$\\rightarrow$$ 4...)</li></ol><hr><h2 id="_3-eklerin-unlu-uyumlarına-uyumu" tabindex="-1">3. Eklerin Ünlü Uyumlarına Uyumu <a class="header-anchor" href="#_3-eklerin-unlu-uyumlarına-uyumu" aria-label="Permalink to “3. Eklerin Ünlü Uyumlarına Uyumu”">​</a></h2><p>Türkçe eklemeli bir dil olduğu için, kelime köklerine getirilen ekler de geldikleri kökün ünlüsüne göre şekil değiştirirler.</p><ul><li><strong>İki şekilli ekler (Büyük ünlü uyumuna göre):</strong> Örn: Çoğul eki <code>-lar / -ler</code>, Yönelme eki <code>-a / -e</code>. Kelime kalınsa <code>-lar</code>, inceyse <code>-ler</code> olur (<em>Taş-lar</em>, <em>Ev-ler</em>).</li><li><strong>Dört şekilli ekler (Hem büyük hem küçük ünlü uyumuna göre):</strong> Örn: İyelik veya soru ekleri <code>-ı / -i / -u / -ü</code>. (<em>Sıra-mız</em>, <em>Evi-miz</em>, <em>Kolu-muz</em>, <em>Gözü-müz</em>).</li></ul><h3 id="istisnai-ekler-uyumsuz-ekler" tabindex="-1">İstisnai Ekler (Uyumsuz Ekler) <a class="header-anchor" href="#istisnai-ekler-uyumsuz-ekler" aria-label="Permalink to “İstisnai Ekler (Uyumsuz Ekler)”">​</a></h3><p>Türkçede bazı ekler kalıplaşmıştır ve kelimenin yapısı ne olursa olsun kendi ünlülerini değiştirmezler. Bu yüzden ünlü uyumlarını bozabilirler:</p><ul><li><strong>-ken:</strong> <em>Bakarken</em> (uyar) / <em>Alırken</em> (bozar)</li><li><strong>-ki:</strong> <em>Onunki</em> (bozar) / <em>Benimki</em> (uyar)</li><li><strong>-yor:</strong> <em>Gidiyor</em> (Küçük ünlü uyumunu her zaman bozar, çünkü sonraki hecede &quot;o&quot; vardır)</li><li><strong>-daş:</strong> <em>Gönüldaş</em> (bozar)</li><li><strong>-leyin:</strong> <em>Sabahleyin</em> (bozar)</li><li><strong>-ımtırak:</strong> <em>Yeşilimtrak</em> (bozar)</li></ul><hr><h2 id="ozet" tabindex="-1">Özet <a class="header-anchor" href="#ozet" aria-label="Permalink to “Özet”">​</a></h2><p>Ünlü uyumları, Türkçenin fonetik karakterini koruyan en büyük kalkandır. Büyük ünlü uyumu dilin kaba hatlarındaki (kalınlık-inceleme) uyumunu sağlarken; küçük ünlü uyumu ise dudak hareketlerinin asgari düzeyde tutularak konuşmanın en az çaba ilkesiyle, akıcı ve yorulmadan yapılmasını sağlar.</p><p>Serimizin 6. bölümünde ses bilgisinin diğer yarısına geçiyoruz: <strong>&quot;Konsonantlar (Ünsüzler) ve Türkçedeki Sınıflandırılması&quot;</strong>.</p><p>Okumaya devam aslanım, sayfayı çeviriyoruz!</p>',34)])])}const c=a(i,[["render",u]]);export{y as __pageData,c as default};
